import{_ as d,o as t,c as o,a2 as c}from"./chunks/framework.BbtkLfwk.js";const b=JSON.parse('{"title":"自动更新 observe","description":"","frontmatter":{},"headers":[],"relativePath":"guide/observe.md","filePath":"guide/observe.md","lastUpdated":1793352003000}'),r={name:"guide/observe.md"};function a(s,e,i,p,l,n){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="自动更新-observe" tabindex="-1">自动更新 observe <a class="header-anchor" href="#自动更新-observe" aria-label="Permalink to &quot;自动更新 observe&quot;">​</a></h1><p>适用于组件和指令。</p><p><code>observe</code> 控制图片 DOM 的自动监听和更新频率。监听范围包括容器内部 <code>&lt;img&gt;</code> 元素的增删、排序和属性变化（如 <code>src</code>、<code>alt</code>），也包括整段 Markdown 或 HTML 替换后产生的图片变化。无关的文字、样式容器和 Viewer.js 自身生成的界面不会触发图库更新。</p><table tabindex="0"><thead><tr><th>值</th><th>行为</th><th>适用场景</th></tr></thead><tbody><tr><td><code>true</code>（默认）</td><td>从首次图片变化开始等待 50ms，将期间的变化合并更新。</td><td>分批渲染的 Markdown、HTML 或短时间连续变化的图片。</td></tr><tr><td><code>0</code></td><td>不额外设置等待窗口，异步执行一次更新；在该次更新执行前发生的图片变化仍会合并。</td><td>变化不频繁、希望尽快更新的图库。</td></tr><tr><td>正数，如 <code>100</code></td><td>将指定毫秒数内的图片变化合并更新。</td><td>更新较频繁，尤其是开启 <code>rebuild</code> 的场景。</td></tr><tr><td><code>false</code></td><td>关闭图片 DOM 自动监听；仍会初始化图库，配置变化和手动 <code>update()</code> 仍然生效。</td><td>内容固定，或由调用者控制更新时间。</td></tr></tbody></table><p>例如，同一次同步操作中连续添加 10 个 <code>&lt;img&gt;</code>，<code>0</code> 也可以合并为一次更新；如果图片分多次异步操作添加，<code>0</code> 可能更新多次，而 <code>50</code> 会合并同一 50ms 窗口内的变化。</p><p>计时从首次图片变化开始，后续变化不会重新计时，持续变化的图库会按窗口定期更新。首次初始化立即执行；等待时间仅用于后续图片 DOM 的自动更新。</p><p>默认更新复用实例并调用 <code>update()</code>；开启 <code>rebuild</code> 后，每批变化改为销毁并重建实例。<code>observe</code> 可动态修改，设为 <code>false</code> 会取消尚未执行的自动更新。</p>',7)])])}const h=d(r,[["render",a]]);export{b as __pageData,h as default};
